function sortNumbers(nums) {
  // BUG: .sort() with no comparator sorts by STRING order, so 10 sorts
  // before 2. Returns a new array (spread) but in the wrong order.
  return [...nums].sort();
}

module.exports = { sortNumbers };

test_setup_files.test_sorter.js:
const assert = require('node:assert');
const { sortNumbers } = require('./sorter.js');

assert.deepStrictEqual(sortNumbers([3, 1, 10, 2, 21]), [1, 2, 3, 10, 21]);
assert.deepStrictEqual(sortNumbers([100, 9, 80]), [9, 80, 100]);
assert.deepStrictEqual(sortNumbers([]), []);
assert.deepStrictEqual(sortNumbers([5]), [5]);

// must not mutate the input
const input = [3, 1, 2];
sortNumbers(input);
assert.deepStrictEqual(input, [3, 1, 2], 'input array was mutated');

console.log('ok');

